'use strict';
// ============================================================
// CHAMELEON — doorgeef-editie
// ============================================================

const APP_VERSION = '2.1.0';

// ---------- helpers ----------
const $ = sel => document.querySelector(sel);
const scr = document.getElementById('screen');

function load(key, fallback){
  try{ const v = JSON.parse(localStorage.getItem(key)); return v == null ? fallback : v; }
  catch(e){ return fallback; }
}
function save(key, val){ try{ localStorage.setItem(key, JSON.stringify(val)); }catch(e){} }
function shuffle(a){
  const arr = a.slice();
  for(let i = arr.length - 1; i > 0; i--){
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}
function pick(a){ return a[Math.floor(Math.random() * a.length)]; }
function esc(s){ return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function topbar(l, r){
  $('#tb-left').textContent = l || '';
  const tr = $('#tb-right');
  tr.textContent = r || '';
  tr.style.display = r ? '' : 'none';
}
function flash(msg){
  const t = $('#toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(t._h);
  t._h = setTimeout(() => t.classList.remove('show'), 2400);
}
// destructieve acties: twee keer tikken
function armConfirm(btn, action){
  if(btn.dataset.armed === '1'){ btn.dataset.armed = ''; action(); return; }
  btn.dataset.armed = '1';
  const old = btn.innerHTML;
  btn.innerHTML = 'Zeker weten? Tik nogmaals';
  setTimeout(() => {
    if(btn.isConnected && btn.dataset.armed === '1'){ btn.dataset.armed = ''; btn.innerHTML = old; }
  }, 2500);
}
function catEmoji(c){ return (typeof CAT_EMOJI !== 'undefined' && CAT_EMOJI[c]) || '📦'; }
function catChip(c){ return '<span class="chip">' + catEmoji(c) + ' ' + esc(c) + '</span>'; }

const AVA_COLORS = ['#FF8FA3','#FFB65C','#5CC98F','#6FB7FF','#B79CFF','#FF9CCF','#8ED16F','#F5A26B'];
function avaColor(name){
  const pi = state.players.indexOf(name);
  return AVA_COLORS[(pi >= 0 ? pi : 0) % AVA_COLORS.length];
}

// mascotte (wordt bij het bouwen ingevuld als data-URI)
const MASCOT_URI = 'data:image/png;base64,';

// ---------- state ----------
const state = {
  players: load('cham_players', []), // array van namen (volgorde = doorgeefvolgorde)
  settings: Object.assign(
    { chameleons: 1, salamanders: 0, chamSeesCategory: true, wordGuess: true, rounds: 5, disabledCats: [] },
    load('cham_settings', {})
  ),
  customWords: load('cham_words', {}), // per categorie: aangepaste woordenlijst
  match: null, // { totalRounds, roundNo, scores: {naam: punten} }
  game: null,  // huidige ronde
  usedWords: {} // per sessie: voorkomt herhaling van woorden
};

// effectieve woordenlijsten: standaard uit words.js + eigen aanpassingen
let LIB = {};
function rebuildLib(){
  LIB = {};
  for(const c of Object.keys(WORDS)){
    LIB[c] = (state.customWords[c] || WORDS[c]).slice();
  }
}

function persistSettings(){ save('cham_settings', state.settings); }
function persistPlayers(){ save('cham_players', state.players); }
function persistWords(){ save('cham_words', state.customWords); rebuildLib(); }
function enabledCategories(){
  return Object.keys(LIB).filter(c =>
    !state.settings.disabledCats.includes(c) && Array.isArray(LIB[c]) && LIB[c].length > 1
  );
}

// ---------- potje & rondes ----------
function startMatch(){
  const n = state.players.length;
  const { chameleons, salamanders } = state.settings;
  if(n < 3){ flash('Je hebt minimaal 3 spelers nodig 👥'); renderPlayers(); return; }
  if(chameleons + salamanders > n - 2){
    flash('Max ' + (n - 2) + ' speciale rollen bij ' + n + ' spelers');
    renderSettings(); return;
  }
  if(enabledCategories().length === 0){ flash('Zet minstens 1 categorie aan'); renderSettings(); return; }
  state.match = {
    totalRounds: state.settings.rounds,
    roundNo: 1,
    scores: Object.fromEntries(state.players.map(nm => [nm, 0]))
  };
  state.game = null;
  renderCategoryPick();
}

function beginRound(catChoice){
  const n = state.players.length;
  const { chameleons, salamanders } = state.settings;
  const cats = enabledCategories();

  const cat = (catChoice && LIB[catChoice]) ? catChoice : pick(cats);

  // geheim woord (zonder herhaling binnen deze sessie)
  let used = state.usedWords[cat] || [];
  let pool = LIB[cat].filter(w => !used.includes(w));
  if(pool.length === 0){ used = []; pool = LIB[cat].slice(); }
  const word = pick(pool);
  state.usedWords[cat] = used.concat([word]);

  // rollen verdelen — elke ronde opnieuw willekeurig
  const roles = new Array(n).fill('speler');
  const order = shuffle([...Array(n).keys()]);
  let k = 0;
  for(let i = 0; i < chameleons; i++) roles[order[k++]] = 'chameleon';

  // salamanders: elk een eigen ánder woord uit dezelfde categorie
  const altPool = shuffle(LIB[cat].filter(w => w !== word));
  const salWordByIndex = {};
  for(let i = 0; i < salamanders; i++){
    const idx = order[k++];
    roles[idx] = 'salamander';
    salWordByIndex[idx] = altPool[i % altPool.length];
  }

  state.game = {
    cat, word,
    players: state.players.map((name, i) => ({
      name,
      role: roles[i],
      word: roles[i] === 'chameleon' ? null
          : roles[i] === 'salamander' ? salWordByIndex[i]
          : word
    })),
    idx: 0,
    starter: pick(state.players), // elke ronde een nieuwe willekeurige beginspeler
    caught: null,
    goodGuess: [],
    scored: false,
    deltas: {}
  };
  renderPass();
}

function applyRoundScores(){
  const g = state.game, m = state.match;
  if(g.scored) return;
  g.scored = true;
  const addPts = (name, pts) => {
    m.scores[name] = (m.scores[name] || 0) + pts;
    g.deltas[name] = (g.deltas[name] || 0) + pts;
  };
  for(const p of g.players){
    if(p.role === 'chameleon'){
      if(!g.caught) addPts(p.name, 2);                    // ontsnapt: +2
      if(g.goodGuess.includes(p.name)) addPts(p.name, 1); // woord goed geraden: +1
    } else if(g.caught){
      addPts(p.name, 1);                                  // chameleon ontmaskerd: iedereen +1
    }
  }
}

function roundLabel(){
  const m = state.match;
  return 'Ronde ' + m.roundNo + '/' + m.totalRounds;
}

// ---------- schermen ----------
function renderHome(){
  state.game = null;
  state.match = null;
  topbar('', 'v' + APP_VERSION);
  const n = state.players.length;
  const cats = Object.keys(LIB).length;
  const total = Object.values(LIB).reduce((a, w) => a + w.length, 0);
  scr.innerHTML = `
    <div class="stack center">
      <div class="hero">
        <img class="mascot" src="${MASCOT_URI}" alt="">
        <h1 class="title">Chameleon</h1>
        <p class="soft">het doorgeef-woordspel</p>
        <p style="margin-top:10px"><span class="chip">${cats} categorieën · ${total} woorden</span></p>
      </div>
      <button class="btn big" id="start">Nieuw potje 🎮</button>
      <button class="btn secondary" id="players">Spelers (${n}) 👥</button>
      <button class="btn secondary" id="settings">Instellingen ⚙️</button>
    </div>`;
  $('#start').onclick = startMatch;
  $('#players').onclick = renderPlayers;
  $('#settings').onclick = renderSettings;
}

function renderPlayers(){
  topbar('Spelers', state.players.length + ' 👥');
  scr.innerHTML = `
    <div class="stack">
      <div class="card" id="plist">
        ${state.players.length
          ? state.players.map((name, i) => `
            <div class="prow">
              <span class="ava" style="background:${AVA_COLORS[i % AVA_COLORS.length]}">${esc(name.charAt(0).toUpperCase())}</span>
              <span class="pname">${esc(name)}</span>
              <button class="del" data-i="${i}" aria-label="verwijder ${esc(name)}">✕</button>
            </div>`).join('')
          : '<p class="soft center">Nog geen spelers… voeg hieronder toe! 👇</p>'}
      </div>
      <div class="addrow">
        <input id="pname" maxlength="14" placeholder="Naam…" autocomplete="off" enterkeyhint="done">
        <button class="btn addbtn" id="add">+</button>
      </div>
      <p class="soft center small">Volgorde in de lijst = doorgeefvolgorde</p>
      <button class="btn subtle" id="back">← Terug</button>
    </div>`;

  const input = $('#pname');
  const add = () => {
    const name = input.value.trim();
    if(!name){ input.focus(); return; }
    if(state.players.some(p => p.toLowerCase() === name.toLowerCase())){
      flash('Die naam is al bezet 😅'); input.select(); return;
    }
    state.players.push(name);
    persistPlayers();
    renderPlayers();
    $('#pname').focus();
  };
  $('#add').onclick = add;
  input.addEventListener('keydown', e => { if(e.key === 'Enter') add(); });
  $('#plist').addEventListener('click', e => {
    const btn = e.target.closest('.del');
    if(!btn) return;
    state.players.splice(Number(btn.dataset.i), 1);
    persistPlayers();
    renderPlayers();
  });
  $('#back').onclick = renderHome;
}

function renderSettings(){
  const s = state.settings;
  const n = state.players.length;
  topbar('Instellingen', '⚙️');
  const cats = Object.keys(LIB);
  const enabledCount = cats.filter(c => !s.disabledCats.includes(c)).length;
  scr.innerHTML = `
    <div class="stack">
      <div class="card">
        <p class="label">Potje</p>
        <div class="srow"><span>🔁 Rondes per potje</span>
          <span class="stepper">
            <button data-k="rounds" data-d="-1">−</button><b>${s.rounds}</b><button data-k="rounds" data-d="1">+</button>
          </span>
        </div>
        <div class="srow" id="guessvis" style="cursor:pointer">
          <span>🔍 Woord raden (+1 punt)</span>
          <span class="switch ${s.wordGuess ? 'on' : ''}"></span>
        </div>
        <p class="soft small">Elke ronde nieuwe rollen en een nieuwe beginspeler. Chameleon ontsnapt = +2 voor de chameleon, ontmaskerd = +1 voor alle anderen. Met woord raden aan mag de chameleon aan het eind het woord raden voor een bonuspunt.</p>
      </div>
      <div class="card">
        <p class="label">Rollen</p>
        <div class="srow"><span>🦎 Chameleons</span>
          <span class="stepper">
            <button data-k="chameleons" data-d="-1">−</button><b>${s.chameleons}</b><button data-k="chameleons" data-d="1">+</button>
          </span>
        </div>
        <div class="srow"><span>🐸 Salamanders</span>
          <span class="stepper">
            <button data-k="salamanders" data-d="-1">−</button><b>${s.salamanders}</b><button data-k="salamanders" data-d="1">+</button>
          </span>
        </div>
        <p class="soft small">De salamander krijgt stiekem een ánder woord — zonder het zelf te weten. Max samen: aantal spelers − 2${n >= 3 ? ' (nu ' + (n - 2) + ')' : ''}.</p>
      </div>
      <div class="card">
        <div class="srow" id="catvis" style="cursor:pointer">
          <span>Chameleon ziet categorie</span>
          <span class="switch ${s.chamSeesCategory ? 'on' : ''}"></span>
        </div>
        <p class="soft small">Uit = hard mode: de chameleon kent ook de categorie niet.</p>
      </div>
      <div class="card">
        <p class="label">Categorieën (${enabledCount}/${cats.length})</p>
        <p class="soft small" style="margin-bottom:4px">Tik op een rij om aan/uit te zetten, op ✏️ om de woorden aan te passen.</p>
        <div id="catlist">
        ${cats.map(c => {
          const on = !s.disabledCats.includes(c);
          const custom = !!state.customWords[c];
          return `<div class="srow cat" data-c="${esc(c)}">
            <span class="catname">${catEmoji(c)} ${esc(c)} <span class="soft small">· ${LIB[c].length}${custom ? ' ✎' : ''}</span></span>
            <button class="editcat" data-c="${esc(c)}" aria-label="bewerk ${esc(c)}">✏️</button>
            <span class="check ${on ? 'on' : ''}">${on ? '✓' : ''}</span>
          </div>`;
        }).join('')}
        </div>
        <div class="two">
          <button class="btn secondary slim" id="allon">Alles aan</button>
          <button class="btn secondary slim" id="alloff">Alles uit</button>
        </div>
      </div>
      <button class="btn subtle" id="back">← Terug</button>
    </div>`;

  scr.querySelectorAll('.stepper button').forEach(btn => {
    btn.onclick = () => {
      const k = btn.dataset.k, d = Number(btn.dataset.d);
      const min = { chameleons: 1, salamanders: 0, rounds: 1 }[k];
      const max = { chameleons: 6, salamanders: 6, rounds: 15 }[k];
      s[k] = Math.min(max, Math.max(min, s[k] + d));
      persistSettings();
      renderSettings();
    };
  });
  $('#catvis').onclick = () => { s.chamSeesCategory = !s.chamSeesCategory; persistSettings(); renderSettings(); };
  $('#guessvis').onclick = () => { s.wordGuess = !s.wordGuess; persistSettings(); renderSettings(); };
  $('#catlist').addEventListener('click', e => {
    const edit = e.target.closest('.editcat');
    if(edit){ renderWordEditor(edit.dataset.c); return; }
    const row = e.target.closest('.cat');
    if(!row) return;
    const c = row.dataset.c;
    const i = s.disabledCats.indexOf(c);
    if(i >= 0) s.disabledCats.splice(i, 1); else s.disabledCats.push(c);
    persistSettings();
    renderSettings();
  });
  $('#allon').onclick = () => { s.disabledCats = []; persistSettings(); renderSettings(); };
  $('#alloff').onclick = () => { s.disabledCats = Object.keys(LIB).slice(); persistSettings(); renderSettings(); };
  $('#back').onclick = renderHome;
}

function renderWordEditor(cat){
  if(!LIB[cat]){ renderSettings(); return; }
  const listArr = LIB[cat];
  const isCustom = !!state.customWords[cat];
  topbar('Woorden', catEmoji(cat));
  scr.innerHTML = `
    <div class="stack">
      <div class="card center" style="padding:12px">
        <span class="chip">${catEmoji(cat)} ${esc(cat)} · ${listArr.length} woorden</span>
        ${isCustom ? '<p class="soft small" style="margin-top:6px">aangepaste lijst ✎</p>' : ''}
        ${listArr.length < 5 ? '<p class="soft small" style="margin-top:6px">⚠️ Weinig woorden — voeg er wat toe voor meer variatie!</p>' : ''}
      </div>
      <div class="addrow">
        <input id="wnew" maxlength="40" placeholder="Nieuw woord…" autocomplete="off" enterkeyhint="done">
        <button class="btn addbtn" id="wadd">+</button>
      </div>
      <div class="card" id="wlist">
        ${listArr.length
          ? listArr.map((w, i) => `
            <div class="wrow" data-i="${i}">
              <span class="wtxt">${esc(w)}</span>
              <button class="del wdel" data-i="${i}" aria-label="verwijder ${esc(w)}">✕</button>
            </div>`).join('')
          : '<p class="soft center">Geen woorden meer… voeg er hierboven toe!</p>'}
      </div>
      ${isCustom ? '<button class="btn secondary slim" id="wreset">Standaardlijst herstellen</button>' : ''}
      <button class="btn subtle" id="back">← Terug naar instellingen</button>
    </div>`;

  const commit = arr => { state.customWords[cat] = arr; persistWords(); renderWordEditor(cat); };

  const input = $('#wnew');
  const addW = () => {
    const w = input.value.trim();
    if(!w){ input.focus(); return; }
    if(LIB[cat].some(x => x.toLowerCase() === w.toLowerCase())){
      flash('Dat woord staat er al in 😅'); input.select(); return;
    }
    commit([w, ...LIB[cat]]);
  };
  $('#wadd').onclick = addW;
  input.addEventListener('keydown', e => { if(e.key === 'Enter') addW(); });

  $('#wlist').addEventListener('click', e => {
    const del = e.target.closest('.wdel');
    if(del){
      const arr = LIB[cat].slice();
      arr.splice(Number(del.dataset.i), 1);
      commit(arr);
      return;
    }
    const txt = e.target.closest('.wtxt');
    if(!txt) return;
    const row = txt.parentElement;
    const i = Number(row.dataset.i);
    row.innerHTML = `
      <input class="wedit" maxlength="40" value="${esc(LIB[cat][i])}">
      <button class="mini ok" aria-label="opslaan">✓</button>
      <button class="mini nope" aria-label="annuleren">✕</button>`;
    const ed = row.querySelector('.wedit');
    ed.focus(); ed.select();
    const saveEdit = () => {
      const w = ed.value.trim();
      if(!w){ renderWordEditor(cat); return; }
      if(LIB[cat].some((x, j) => j !== i && x.toLowerCase() === w.toLowerCase())){
        flash('Dat woord staat er al in 😅'); return;
      }
      const arr = LIB[cat].slice();
      arr[i] = w;
      commit(arr);
    };
    row.querySelector('.ok').onclick = saveEdit;
    row.querySelector('.nope').onclick = () => renderWordEditor(cat);
    ed.addEventListener('keydown', ev => { if(ev.key === 'Enter') saveEdit(); });
  });

  if(isCustom){
    $('#wreset').onclick = e => armConfirm(e.currentTarget, () => {
      delete state.customWords[cat];
      persistWords();
      renderWordEditor(cat);
    });
  }
  $('#back').onclick = renderSettings;
}

function renderCategoryPick(){
  topbar(roundLabel(), 'categorie');
  const cats = enabledCategories();
  const hardHint = !state.settings.chamSeesCategory
    ? '<div class="note">🤫 Hard mode staat aan — kies <b>willekeurig</b>, anders ziet de chameleon de categorie hier alsnog!</div>'
    : '';
  scr.innerHTML = `
    <div class="stack">
      <h2 class="h2">Kies een categorie</h2>
      ${hardHint}
      <button class="btn big" id="rand">🎲&nbsp; Willekeurige categorie</button>
      <div class="catgrid">
        ${cats.map(c => `
          <div class="catcard" data-c="${esc(c)}">
            <div class="em">${catEmoji(c)}</div>
            <div class="nm">${esc(c)}</div>
            <div class="ct">${LIB[c].length} woorden</div>
          </div>`).join('')}
      </div>
      <button class="btn subtle" id="abort">✕ Potje stoppen</button>
    </div>`;
  $('#rand').onclick = () => beginRound(null);
  scr.querySelectorAll('.catcard').forEach(el => { el.onclick = () => beginRound(el.dataset.c); });
  $('#abort').onclick = e => armConfirm(e.currentTarget, renderHome);
}

function renderPass(){
  const g = state.game;
  const p = g.players[g.idx];
  topbar(roundLabel(), 'speler ' + (g.idx + 1) + '/' + g.players.length);
  scr.innerHTML = `
    <div class="stack center">
      <p class="soft" style="margin-top:26px">Geef de telefoon aan</p>
      <h1 class="passname">${esc(p.name)}</h1>
      <button class="btn big" id="me">Ik ben ${esc(p.name)}! 👋</button>
      <button class="btn subtle" id="abort">✕ Ronde stoppen</button>
    </div>`;
  $('#me').onclick = renderRole;
  $('#abort').onclick = e => armConfirm(e.currentTarget, renderHome);
}

function fillRoleCard(card, p, g){
  if(p.role === 'chameleon'){
    const catLine = state.settings.chamSeesCategory
      ? catChip(g.cat)
      : '<span class="chip">❓ categorie geheim</span>';
    card.innerHTML = `
      <div class="pop">
        <div class="rolemoji">🦎</div>
        <p class="soft">Ssst… jij bent</p>
        <div class="bigword red">de CHAMELEON!</div>
        <p style="margin:10px 0">${catLine}</p>
        <p class="soft">Doe alsof je het woord kent 😏</p>
      </div>`;
  } else {
    // gewone speler én salamander: exact hetzelfde scherm
    card.innerHTML = `
      <div class="pop">
        <p style="margin-bottom:10px">${catChip(g.cat)}</p>
        <p class="soft">Het geheime woord is</p>
        <div class="bigword">${esc(p.word)}</div>
        <p class="soft">Verklap het niet letterlijk 😉</p>
      </div>`;
  }
}

function renderRole(){
  const g = state.game;
  const p = g.players[g.idx];
  topbar(roundLabel(), 'speler ' + (g.idx + 1) + '/' + g.players.length);
  scr.innerHTML = `
    <div class="stack">
      <h2 class="h2 center" style="margin-top:6px">Hoi ${esc(p.name)}! 👋</h2>
      <div id="hold" class="holdzone">
        <div class="holdhint">
          <div class="rolemoji">🤫</div>
          <p class="soft"><b>Houd ingedrukt</b><br>om je geheime rol te zien</p>
        </div>
        <div class="holdcontent hidden" id="rolecard"></div>
      </div>
      <p class="soft center small" id="seenmark">&nbsp;</p>
      <button class="btn big" id="nextbtn" disabled>Verbergen &amp; doorgeven ➜</button>
    </div>`;

  const hold = $('#hold');
  const card = $('#rolecard');
  const hint = hold.querySelector('.holdhint');
  let seen = false;

  const show = e => {
    e.preventDefault();
    hint.classList.add('hidden');
    card.classList.remove('hidden');
    hold.classList.add('active');
    fillRoleCard(card, p, g);
    if(!seen){
      seen = true;
      $('#nextbtn').disabled = false;
      $('#seenmark').textContent = 'Rol bekeken ✓';
    }
  };
  const hide = () => {
    card.classList.add('hidden');
    hint.classList.remove('hidden');
    hold.classList.remove('active');
  };
  hold.addEventListener('pointerdown', show);
  ['pointerup', 'pointerleave', 'pointercancel'].forEach(ev => hold.addEventListener(ev, hide));
  hold.addEventListener('contextmenu', e => e.preventDefault());

  $('#nextbtn').onclick = () => {
    g.idx++;
    if(g.idx < g.players.length) renderPass(); else renderDiscussion();
  };
}

function renderDiscussion(){
  const g = state.game;
  topbar(roundLabel(), 'hintronde');
  const catLine = state.settings.chamSeesCategory
    ? catChip(g.cat)
    : '<span class="chip">❓ categorie geheim</span> <span class="soft small">(hard mode)</span>';
  scr.innerHTML = `
    <div class="stack">
      <div class="card center">
        <div class="rolemoji">🎉</div>
        <h2 class="h2">Iedereen heeft gekeken!</h2>
        <p style="margin-top:10px">${catLine}</p>
      </div>
      <div class="card">
        <p>👉 <b>${esc(g.starter)}</b> begint met een hint</p>
        <p>🔁 Daarna met de klok mee</p>
        <p>💬 Eén woord per hint</p>
        <p>🗳️ Stem daarna: wie is de chameleon?</p>
      </div>
      <button class="btn big" id="reveal">Onthulling 🎭</button>
      <button class="btn subtle" id="abort">✕ Stoppen</button>
    </div>`;
  $('#reveal').onclick = renderReveal0;
  $('#abort').onclick = e => armConfirm(e.currentTarget, renderHome);
}

function renderReveal0(){
  topbar(roundLabel(), 'onthulling');
  scr.innerHTML = `
    <div class="stack center">
      <div class="card">
        <div class="rolemoji">🙈</div>
        <h2 class="h2">Iedereen mag nu meekijken</h2>
        <p class="soft" style="margin-top:8px">Eerst stemmen, dán onthullen!</p>
      </div>
      <button class="btn big" id="b">Onthul de rollen 🥁</button>
      <button class="btn subtle" id="back">← Terug</button>
    </div>`;
  $('#b').onclick = renderRevealRoles;
  $('#back').onclick = renderDiscussion;
}

function renderRevealRoles(){
  const g = state.game;
  topbar(roundLabel(), 'onthulling');
  const chams = g.players.filter(p => p.role === 'chameleon');
  const sals = g.players.filter(p => p.role === 'salamander');
  scr.innerHTML = `
    <div class="stack">
      <div class="card center">
        <p class="label red">🦎 De chameleon${chams.length > 1 ? 's' : ''}</p>
        ${chams.map(p => `<div class="revealname red">${esc(p.name)}</div>`).join('')}
      </div>
      ${sals.length ? `
      <div class="card center">
        <p class="label orange">🐸 De salamander${sals.length > 1 ? 's' : ''}</p>
        ${sals.map(p => `<div class="revealname orange">${esc(p.name)}</div>`).join('')}
      </div>` : ''}
      <div class="card center">
        <h2 class="h2">🗳️ ${chams.length > 1 ? 'Zijn de chameleons' : 'Is de chameleon'} ontmaskerd?</h2>
      </div>
      <button class="btn big" id="yes">Ja, gepakt! 🎯</button>
      <button class="btn secondary" id="no">Nee, ontsnapt! 🏃</button>
    </div>`;
  const next = () => state.settings.wordGuess ? renderGuessIntro() : renderWordReveal(false);
  $('#yes').onclick = () => { g.caught = true; next(); };
  $('#no').onclick = () => { g.caught = false; next(); };
}

function renderGuessIntro(){
  const g = state.game;
  topbar(roundLabel(), 'woord raden');
  const chams = g.players.filter(p => p.role === 'chameleon');
  const names = chams.map(p => esc(p.name)).join(' & ');
  scr.innerHTML = `
    <div class="stack center">
      <div class="card">
        <div class="rolemoji">🤔</div>
        <h2 class="h2">${names} mag nu het woord raden</h2>
        <p class="soft" style="margin-top:8px">Hardop zeggen — goed geraden = <b>+1 punt</b>!</p>
      </div>
      <button class="btn big" id="b">Toon het woord 🔍</button>
    </div>`;
  $('#b').onclick = () => renderWordReveal(true);
}

function renderWordReveal(judge){
  const g = state.game;
  topbar(roundLabel(), 'het woord');
  const chams = g.players.filter(p => p.role === 'chameleon');
  const sals = g.players.filter(p => p.role === 'salamander');
  let judgeBlock = '';
  if(judge && chams.length === 1){
    judgeBlock = `
      <div class="card center">
        <h2 class="h2">Had ${esc(chams[0].name)} het goed?</h2>
      </div>
      <button class="btn big" id="gyes">Ja, goed geraden! 🎯</button>
      <button class="btn secondary" id="gno">Nee, fout 🙅</button>`;
  } else if(judge){
    judgeBlock = `
      <div class="card">
        <p class="label">Wie raadde het woord goed?</p>
        ${chams.map(p => `
          <div class="srow guessrow" data-n="${esc(p.name)}" style="cursor:pointer">
            <span>${esc(p.name)}</span><span class="switch"></span>
          </div>`).join('')}
      </div>
      <button class="btn big" id="go">Naar de punten ➜</button>`;
  } else {
    judgeBlock = '<button class="btn big" id="go">Naar de punten ➜</button>';
  }
  scr.innerHTML = `
    <div class="stack">
      <div class="card center">
        <p style="margin-bottom:10px">${catChip(g.cat)}</p>
        <p class="soft">Het woord was</p>
        <div class="bigword pop">${esc(g.word)}</div>
      </div>
      ${sals.length ? `
      <div class="card">
        <p class="label orange">De salamander${sals.length > 1 ? 's dachten' : ' dacht'}…</p>
        ${sals.map(p => `<p>🐸 <b>${esc(p.name)}</b> dacht dat het "<b>${esc(p.word)}</b>" was</p>`).join('')}
      </div>` : ''}
      ${judgeBlock}
    </div>`;

  if(judge && chams.length === 1){
    $('#gyes').onclick = () => { g.goodGuess = [chams[0].name]; renderRoundResult(); };
    $('#gno').onclick = () => { g.goodGuess = []; renderRoundResult(); };
  } else if(judge){
    scr.querySelectorAll('.guessrow').forEach(row => {
      row.onclick = () => row.querySelector('.switch').classList.toggle('on');
    });
    $('#go').onclick = () => {
      g.goodGuess = [...scr.querySelectorAll('.guessrow')]
        .filter(r => r.querySelector('.switch').classList.contains('on'))
        .map(r => r.dataset.n);
      renderRoundResult();
    };
  } else {
    g.goodGuess = [];
    $('#go').onclick = renderRoundResult;
  }
}

function renderRoundResult(){
  applyRoundScores();
  const g = state.game, m = state.match;
  topbar(roundLabel(), 'punten');
  const standings = Object.entries(m.scores).sort((a, b) => b[1] - a[1]);
  const last = m.roundNo >= m.totalRounds;
  scr.innerHTML = `
    <div class="stack">
      <div class="card center" style="padding:12px">
        <span class="chip">${g.caught ? '🎯 Chameleon ontmaskerd: iedereen +1' : '🏃 Chameleon ontsnapt: chameleon +2'}</span>
        ${g.goodGuess.length ? '<p class="soft small" style="margin-top:6px">🔍 Woord goed geraden: +1 bonus</p>' : ''}
      </div>
      <div class="card">
        <p class="label">Tussenstand</p>
        ${standings.map(([name, pts], i) => {
          const d = g.deltas[name] || 0;
          return `<div class="prow">
            <span class="rank">${i + 1}</span>
            <span class="ava" style="background:${avaColor(name)}">${esc(name.charAt(0).toUpperCase())}</span>
            <span class="pname">${esc(name)}</span>
            ${d ? `<span class="delta">+${d}</span>` : ''}
            <span class="score">${pts}</span>
          </div>`;
        }).join('')}
      </div>
      <button class="btn big" id="next">${last ? 'Bekijk de eindstand 🏆' : 'Volgende ronde ➜'}</button>
      <button class="btn subtle" id="abort">✕ Potje stoppen</button>
    </div>`;
  $('#next').onclick = () => {
    if(last){ renderFinal(); }
    else { m.roundNo++; renderCategoryPick(); }
  };
  $('#abort').onclick = e => armConfirm(e.currentTarget, renderHome);
}

function renderFinal(){
  const m = state.match;
  topbar('Eindstand', '🏆');
  const standings = Object.entries(m.scores).sort((a, b) => b[1] - a[1]);
  const top = standings.length ? standings[0][1] : 0;
  const winners = standings.filter(([, p]) => p === top).map(([n]) => n);
  const medals = ['🥇', '🥈', '🥉'];
  scr.innerHTML = `
    <div class="stack">
      <div class="card center">
        <div class="rolemoji">🏆</div>
        <h2 class="h2">${winners.map(esc).join(' & ')} ${winners.length > 1 ? 'winnen' : 'wint'}!</h2>
        <p class="soft" style="margin-top:6px">met ${top} punt${top === 1 ? '' : 'en'}</p>
      </div>
      <div class="card">
        ${standings.map(([name, pts], i) => `
          <div class="prow">
            <span class="rank">${pts === top ? '🥇' : (medals[i] || (i + 1))}</span>
            <span class="ava" style="background:${avaColor(name)}">${esc(name.charAt(0).toUpperCase())}</span>
            <span class="pname">${esc(name)}</span>
            <span class="score">${pts}</span>
          </div>`).join('')}
      </div>
      <button class="btn big" id="again">Nieuw potje 🔁</button>
      <button class="btn subtle" id="home">Home</button>
    </div>`;
  $('#again').onclick = startMatch;
  $('#home').onclick = renderHome;
}

// ---------- init ----------
rebuildLib();
renderHome();

if('serviceWorker' in navigator){
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js').catch(() => {});
  });
}
